  option('TimePanel','onHoverChange','function(value, detail)','undefined','指针 hover cell 时返回预览 time，不直接提交 value。');
  event('TimePanel','onHoverChange','function(value, detail)','cell hover preview 变化；离开时 value 为 null。');

  option('Trigger','offset','number | object','8 (12 when arrow)','reference 与 floating 的主轴偏移；arrow=true 且未显式传 offset 时默认 12。');
  option('Trigger','arrow','boolean','false','声明 floating 带 arrow，并调整默认 offset。');
