  option('Trigger','inlinePositioning','boolean','false','启用 inline reference positioning。');
  option('Trigger','inlinePositioningOptions','object | undefined','undefined','inline positioning 配置。');
  option('Trigger','interactiveBorder','number','0','hover/focus interaction 的安全区。');
  option('Trigger','interactiveDebounce','number','0','交互安全区关闭 debounce。');
  option('Trigger','zIndex','number | null','null','交给 LayerManager 的显式 z-index override。');
  option('Trigger','positionReference','virtual reference | null','null','仅改变定位几何 reference；真实 trigger/reference ownership 不变。');
  option('Trigger','useTransformPosition','boolean','false','由定位层使用 transform 投影 geometry；visual transition owner 仍应独立。');

  option('Message','key','string','auto','稳定消息 key；重复 key 用于 update，而不是创建重复 notice。');
  option('Message','closeOnClick','boolean','false','点击消息主体时关闭。');
