  option('Message','stackStyle','style object | null','null','stack container inline style。');
  option('Message','zIndex','number | null','null','显式 stack z-index；默认由 NoticeService / LayerManager 管理。');
  ['onOpen','onBeforeClose','onClose','onUpdate'].forEach(function(n){option('Message',n,'function','undefined','Message notice lifecycle callback。');event('Message',n,'function(detail)','Message notice lifecycle event/callback。');});

  option('Notification','key','string','auto','稳定 notification key；重复 key 用于 update。');
  option('Notification','placement','top-left | top | top-right | left-center | center | right-center | bottom-left | bottom | bottom-right','top-right','九宫格 placement；stack geometry 由 NoticeService 统一拥有。');
  option('Notification','closeOnClick','boolean','false','点击通知主体时关闭。');
  option('Notification','stackClassName','string','', 'stack container className。');
  option('Notification','stackStyle','style object | null','null','stack container inline style。');
  option('Notification','zIndex','number | null','null','显式 stack z-index；默认由共享 overlay 层管理。');
  ['onOpen','onAction','onBeforeClose','onClose','onUpdate'].forEach(function(n){option('Notification',n,'function','undefined','Notification lifecycle/action callback。');event('Notification',n,'function(detail)','Notification lifecycle/action event/callback。');});

  option('Tabs','activeKey','string | number','derived','受控当前 tab key；存在时覆盖 defaultActiveKey。');
